package com.instrua.waitlist;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.UUID; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/webhook/whatsapp") public class WhatsAppWebhookController {
 private final WaitlistService waitlist; private final ObjectMapper mapper; private final String appSecret,verifyToken;
 public WhatsAppWebhookController(WaitlistService s,ObjectMapper m,@Value("\${instrua.whatsapp.app-secret:}") String secret,@Value("\${instrua.whatsapp.verify-token:}") String verifyToken){waitlist=s;mapper=m;appSecret=secret;this.verifyToken=verifyToken;}
 @GetMapping public String verify(@RequestParam("hub.mode") String mode,@RequestParam("hub.verify_token") String token,@RequestParam("hub.challenge") String challenge){if("subscribe".equals(mode)&&!verifyToken.isBlank()&&MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),verifyToken.getBytes(StandardCharsets.UTF_8)))return challenge;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Webhook verification failed");}
 @PostMapping("/{companyId}") @ResponseStatus(HttpStatus.OK) public void receive(@PathVariable UUID companyId,@RequestHeader(value="X-Hub-Signature-256",required=false) String signature,@RequestBody byte[] raw){if(!validSignature(raw,signature))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid webhook signature");try{JsonNode root=mapper.readTree(raw);JsonNode messages=root.path("entry").path(0).path("changes").path(0).path("value").path("messages");if(!messages.isArray())return;for(JsonNode msg:messages){String phone=msg.path("from").asText();String body=msg.path("text").path("body").asText("").trim().toUpperCase(java.util.Locale.ROOT);if(body.equals("SIM")||body.equals("SIM!"))waitlist.respond(companyId,phone,true);else if(body.equals("NÃO")||body.equals("NAO"))waitlist.respond(companyId,phone,false);}}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid webhook payload");}}
 private boolean validSignature(byte[] body,String signature){if(appSecret.isBlank()||signature==null||!signature.startsWith("sha256="))return false;try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(appSecret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] expected=("sha256="+java.util.HexFormat.of().formatHex(mac.doFinal(body))).getBytes(StandardCharsets.UTF_8);return MessageDigest.isEqual(expected,signature.getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
}
